/* SPDX-License-Identifier: Apache-2.0
 * OM-2 qualification, lane s5s7 (#748, ledger L836): SHA consumer-semantics ORACLE driver for
 * contract section 7 (spec/omegese-om2.md lines 212-223) and erratum E3. Outside the delivered
 * closure. Expected digests: expected.h, generated by ../oracle.py with python3 hashlib.
 *
 * Built against the bridge-GENERATED declaration header (contract 216-217, E3: it maps sha256_* to
 * omega2_sha256_*); its file name is not fixed by the contract, so it is passed as GENHDR:
 *   gcc -std=gnu11 -O2 -Wall -Wextra -Werror -DGENHDR='"<generated header>"' -I<dir> \
 *       sha_driver.c <generated binding/library> -o sha_driver
 * Self-check of this driver (NOT OM-2 evidence): the same file built against the CURRENT
 * src/sha256.c/.h of main acb3f15 (-DGENHDR='"sha256.h"' -I/tmp/zl/main/src /tmp/zl/main/src/sha256.c).
 * Usage: sha_driver [big]   ("big" adds the >= 2^32-byte update cases; needs 4 GiB of address
 * space, read from the shared zero page, no resident memory).
 * Output: one PASS/FAIL line per case id (ids match candidate.cases sha-* rows); exit 0 iff no FAIL. */
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>

#ifndef GENHDR
#define GENHDR "sha256.h"
#endif
#include GENHDR
#include "expected.h"

static int fails;
static void check(const char *id, int ok, const char *what)
{
    printf("%s %s %s\n", ok ? "PASS" : "FAIL", id, what);
    if (!ok)
        fails++;
}

static int eqhex(const uint8_t *d, const char *hex)
{
    static const char x[] = "0123456789abcdef";
    int i;
    for (i = 0; i < 32; i++)
        if (hex[2 * i] != x[d[i] >> 4] || hex[2 * i + 1] != x[d[i] & 15])
            return 0;
    return hex[64] == 0;
}

static uint8_t msg[1000];

int main(int argc, char **argv)
{
    sha256_ctx c, c2;
    uint8_t d[32], d2[32];
    static uint8_t ov[96];
    size_t i, k;
    int ok;

    for (i = 0; i < sizeof msg; i++)
        msg[i] = (uint8_t)(i % 251);
    sha256_init(&c);
    sha256_final(&c, d);
    check("sha-empty", eqhex(d, EXP_EMPTY), "init, final = sha256(\"\")");
    sha256_init(&c);
    sha256_update(&c, (const uint8_t *)"abc", 3);
    sha256_final(&c, d);
    check("sha-abc", eqhex(d, EXP_ABC), "abc");
    /* any split point (contract 214-215) */
    ok = 1;
    for (k = 0; k <= sizeof msg; k++) {
        sha256_init(&c);
        sha256_update(&c, msg, k);
        sha256_update(&c, msg + k, sizeof msg - k);
        sha256_final(&c, d);
        ok &= eqhex(d, EXP_SEQ1000);
    }
    check("sha-split2", ok, "every two-way split k = 0..1000 of seq:1000");
    ok = 1;
    for (k = 0; k <= sizeof msg; k += 7) {
        size_t j = (k * 13) % (sizeof msg - k + 1);
        sha256_init(&c);
        sha256_update(&c, msg, 0);
        sha256_update(&c, msg, k);
        sha256_update(&c, msg + k, 0);
        sha256_update(&c, msg + k, j);
        sha256_update(&c, msg + k + j, sizeof msg - k - j);
        sha256_update(&c, msg, 0);
        sha256_final(&c, d);
        ok &= eqhex(d, EXP_SEQ1000);
    }
    check("sha-split3-zero", ok, "three-way splits with length-0 updates between them");
    sha256_init(&c);
    for (i = 0; i < sizeof msg; i++)
        sha256_update(&c, msg + i, 1);
    sha256_final(&c, d);
    check("sha-bytewise", eqhex(d, EXP_SEQ1000), "1000 one-byte updates");
    sha256_init(&c);
    sha256_update(&c, NULL, 0);
    sha256_final(&c, d);
    check("sha-update-null0", eqhex(d, EXP_EMPTY), "update(NULL, 0) is an empty update (ABI: len 0 any pointer)");
    /* digest overlapping data (contract 214-215, E3) */
    memcpy(ov, msg, 64);
    sha256_hash(ov, 64, ov);
    check("sha-hash-overlap0", eqhex(ov, EXP_SEQ64), "sha256_hash(buf, 64, buf)");
    memcpy(ov, msg, 64);
    sha256_hash(ov, 64, ov + 16);
    check("sha-hash-overlap16", eqhex(ov + 16, EXP_SEQ64), "sha256_hash(buf, 64, buf + 16)");
    memcpy(ov + 32, msg, 64);
    sha256_hash(ov + 32, 64, ov + 8);
    check("sha-hash-overlap-before", eqhex(ov + 8, EXP_SEQ64), "digest [8,40) overlapping data [32,96)");
    /* post-final reuse (contract 219-222) */
    sha256_init(&c);
    sha256_update(&c, (const uint8_t *)"abc", 3);
    sha256_final(&c, d);
    sha256_init(&c);
    sha256_update(&c, msg, sizeof msg);
    sha256_final(&c, d);
    check("sha-post-final", eqhex(d, EXP_SEQ1000), "init, update, final after a final == fresh context");
    sha256_update(&c, msg, 10);
    sha256_final(&c, d2);
    check("sha-no-init-safe", 1, "update, final without init returned (digest unspecified; memory safety only)");
    /* hash(n) == init, update(n), final (contract 223) */
    ok = 1;
    for (i = 0; i < sizeof exp_hash_n / sizeof exp_hash_n[0]; i++) {
        size_t n = exp_hash_n[i];
        sha256_hash(msg, n, d);
        sha256_init(&c);
        sha256_update(&c, msg, n);
        sha256_final(&c, d2);
        ok &= eqhex(d, exp_hash_d[i]) && memcmp(d, d2, 32) == 0;
    }
    check("sha-hash-eq-stream", ok, "hash(n) == init, update(n), final == python, n in {0,1,55,56,63,64,65,119,120,1000}");
    /* context byte copy is equivalent (erratum E3) */
    ok = 1;
    for (k = 0; k <= 200; k += 25) {
        sha256_init(&c);
        sha256_update(&c, msg, k);
        memcpy(&c2, &c, sizeof c);
        sha256_update(&c, msg + k, sizeof msg - k);
        sha256_update(&c2, msg + k, sizeof msg - k);
        sha256_final(&c, d);
        sha256_final(&c2, d2);
        ok &= eqhex(d, EXP_SEQ1000) && eqhex(d2, EXP_SEQ1000);
    }
    check("sha-ctx-copy", ok, "byte copy after k updates, both continued: equal digests (E3)");
    /* updates of at least 2^32 bytes (contract 214) */
    if (argc > 1 && strcmp(argv[1], "big") == 0) {
        uint8_t *z = mmap(NULL, (size_t)EXP_BIG_LEN, PROT_READ, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
        if (z == MAP_FAILED) {
            printf("NOT_RUN sha-big-1 mmap failed\nNOT_RUN sha-big-split mmap failed\n");
        } else {
            sha256_init(&c);
            sha256_update(&c, z, (size_t)EXP_BIG_LEN);
            sha256_final(&c, d);
            check("sha-big-1", eqhex(d, EXP_BIG_ZERO), "one update of 2^32+3 zero bytes");
            sha256_init(&c);
            sha256_update(&c, z, (size_t)0xffffffffu);
            sha256_update(&c, z, 4);
            sha256_final(&c, d);
            check("sha-big-split", eqhex(d, EXP_BIG_ZERO), "updates of 2^32-1 and 4 zero bytes");
            sha256_hash(z, (size_t)EXP_BIG_LEN, d);
            check("sha-big-hash", eqhex(d, EXP_BIG_ZERO), "hash of 2^32+3 zero bytes");
            munmap(z, (size_t)EXP_BIG_LEN);
        }
    } else {
        printf("NOT_RUN sha-big-1 sha-big-split sha-big-hash (run with argument big)\n");
    }
    printf("%s SHA driver: %d failure(s)\n", fails ? "FAIL" : "PASS", fails);
    return fails ? 1 : 0;
}
